const ROMAN_VALUES = [
  [1000, 'M'], [900, 'CM'], [500, 'D'], [400, 'CD'], [100, 'C'], [90, 'XC'],
  [50, 'L'], [40, 'XL'], [10, 'X'], [9, 'IX'], [5, 'V'], [4, 'IV'], [1, 'I'],
];

export default {
  section: 'Day 15: String',
  problems: [
    {
      slug: 'reverse-words-in-a-string',
      title: 'Reverse Words in a String',
      difficulty: 'Medium',
      topic: 'Strings',
      description: `Given a string with words separated by spaces (possibly extra leading, trailing or repeated spaces), reverse the order of the words and normalize the spacing: exactly one space between words and no spaces at the ends.

Input format: one line containing the string (it contains at least one word).

{{EXAMPLES}}`,
      constraints: '1 <= length of line <= 10^4\nThe line contains at least one non-space character',
      inputs: [
        'the sky is blue',
        '  hello world  ',
        'a good   example',
        'single',
        '   one   two three   four  ',
        'reverse me',
        '   spaces     everywhere    ',
      ],
      solve(input) {
        const line = input.split('\n')[0];
        return line.split(/\s+/).filter(Boolean).reverse().join(' ');
      },
    },
    {
      slug: 'longest-palindromic-substring',
      title: 'Longest Palindromic Substring',
      difficulty: 'Medium',
      topic: 'Strings',
      description: `Given a string, find its longest contiguous substring that reads the same forwards and backwards.

If several substrings share the maximum length, print the one that **starts earliest**.

Input format: one line containing the string (at least one character).

{{EXAMPLES}}`,
      constraints: '1 <= |S| <= 1000\nS contains lowercase letters and digits only',
      inputs: ['babad', 'cbbd', 'a', 'ac', 'forgeeksskeegfor', 'abcda', 'aaaa'],
      solve(input) {
        const s = input.trim().split('\n')[0];
        let bestStart = 0, bestLen = 1;
        const expand = (left, right) => {
          let l = left, r = right;
          while (l >= 0 && r < s.length && s[l] === s[r]) { l--; r++; }
          const len = r - l - 1;
          const start = l + 1;
          if (len > bestLen || (len === bestLen && start < bestStart)) {
            bestLen = len;
            bestStart = start;
          }
        };
        for (let i = 0; i < s.length; i++) {
          expand(i, i);
          expand(i, i + 1);
        }
        return s.slice(bestStart, bestStart + bestLen);
      },
    },
    {
      slug: 'roman-to-integer',
      title: 'Roman to Integer',
      difficulty: 'Easy',
      topic: 'Strings',
      description: `Convert a Roman numeral to its integer value.

Roman symbols: \`I = 1, V = 5, X = 10, L = 50, C = 100, D = 500, M = 1000\`. A smaller symbol before a larger one subtracts (\`IV = 4\`, \`IX = 9\`, \`XL = 40\`, \`XC = 90\`, \`CD = 400\`, \`CM = 900\`); otherwise values add.

Input format: one line containing the Roman numeral.

{{EXAMPLES}}`,
      constraints: '1 <= |S| <= 15\nS is a valid Roman numeral between 1 and 3999',
      inputs: ['XIV', 'MCMXCIV', 'III', 'IX', 'MMXXIV', 'XLII', 'CDIX'],
      solve(input) {
        const s = input.trim().split('\n')[0];
        const value = { I: 1, V: 5, X: 10, L: 50, C: 100, D: 500, M: 1000 };
        let total = 0;
        for (let i = 0; i < s.length; i++) {
          const cur = value[s[i]];
          const next = value[s[i + 1]];
          total += next > cur ? -cur : cur;
        }
        return String(total);
      },
    },
    {
      slug: 'integer-to-roman',
      title: 'Integer to Roman',
      difficulty: 'Medium',
      topic: 'Strings',
      description: `Convert an integer between 1 and 3999 into its Roman numeral representation using the standard subtractive forms (\`IV, IX, XL, XC, CD, CM\`).

Input format: one line containing the integer.

{{EXAMPLES}}`,
      constraints: '1 <= n <= 3999',
      inputs: ['3', '58', '1994', '9', '40', '3999', '2024'],
      solve(input) {
        let n = Number(input.trim());
        let out = '';
        for (const [value, symbol] of ROMAN_VALUES) {
          while (n >= value) {
            out += symbol;
            n -= value;
          }
        }
        return out;
      },
    },
    {
      slug: 'atoi-string-to-integer',
      title: 'String to Integer (atoi)',
      difficulty: 'Medium',
      topic: 'Strings',
      description: `Implement \`atoi\`: convert the start of a string to a 32-bit signed integer.

Rules, in order:
1. skip any leading whitespace;
2. accept an optional \`+\` or \`-\` sign;
3. read the following digits (stop at the first non-digit);
4. if no digits were read, the result is \`0\`;
5. clamp the result into \`[-2^31, 2^31 - 1]\` (i.e. \`-2147483648\` to \`2147483647\`).

Input format: one line containing the string (may be empty or whitespace only).

{{EXAMPLES}}`,
      constraints: '0 <= |S| <= 200\nS may contain letters, symbols and spaces',
      inputs: [
        '42',
        '   -42',
        '4193 with words',
        'words and 987',
        '+1',
        '-91283472332',
        '  +00000123',
      ],
      solve(input) {
        const s = input.split('\n')[0] ?? '';
        const match = s.match(/^\s*([+-]?)(\d+)/);
        if (!match) return '0';
        let value = Number(match[2]);
        if (match[1] === '-') value = -value;
        if (value > 2147483647) value = 2147483647;
        if (value < -2147483648) value = -2147483648;
        return String(value);
      },
    },
    {
      slug: 'implement-strstr',
      title: 'Implement strStr() (find first occurrence)',
      difficulty: 'Easy',
      topic: 'Strings',
      description: `Given a text and a pattern, find the **first** position where the pattern occurs in the text (0-based). If it never occurs, print \`-1\`. An empty pattern matches at position \`0\`.

Input format: first line the text, second line the pattern (both contain no spaces or newlines).

{{EXAMPLES}}`,
      constraints: '0 <= |text|, |pattern| <= 10^5\nBoth strings contain lowercase letters only',
      inputs: [
        'sadbutsad\nsad',
        'leetcode\nleeto',
        'hello\nll',
        'abc\n',
        'aaaaa\nbba',
        'ababcabc\nabc',
        'needle\nhaystack',
      ],
      solve(input) {
        const lines = input.split('\n');
        const text = lines[0] ?? '';
        const pattern = lines[1] ?? '';
        return String(text.indexOf(pattern));
      },
    },
    {
      slug: 'longest-common-prefix',
      title: 'Longest Common Prefix',
      difficulty: 'Easy',
      topic: 'Strings',
      description: `Given \`N\` strings, find the longest common prefix shared by all of them — the longest string that is at the start of every given string.

If there is no common prefix, print \`-1\`.

Input format: first line \`N\`, second line the \`N\` strings separated by spaces.

{{EXAMPLES}}`,
      constraints: '1 <= N <= 1000\n1 <= length of each string <= 1000\nStrings contain lowercase letters and digits only',
      inputs: [
        '3\nflower flow flight',
        '2\ndog cat',
        '2\ninterspace intern',
        '1\nsolo',
        '4\nprefix prefixes pre preface',
        '3\na b c',
        '3\n123 12345 1234',
      ],
      solve(input) {
        const lines = input.trim().split('\n');
        const N = Number(lines[0]);
        const words = lines[1].split(/\s+/).slice(0, N);
        let prefix = words[0];
        for (const word of words) {
          while (!word.startsWith(prefix)) prefix = prefix.slice(0, -1);
          if (!prefix) break;
        }
        return prefix || '-1';
      },
    },
    {
      slug: 'rabin-karp-pattern-search',
      title: 'Rabin-Karp Pattern Searching',
      difficulty: 'Medium',
      topic: 'Strings',
      description: `Find **all** occurrences of a pattern in a text using rolling-hash style matching (any correct method is fine, but the output must list every match).

Input format: first line the text, second line the pattern (no spaces or newlines; the pattern is non-empty).

Print all match positions (0-based) in increasing order, separated by single spaces. If there are no matches, print \`-1\`.

{{EXAMPLES}}`,
      constraints: '1 <= |text|, |pattern| <= 10^5\nBoth strings contain lowercase letters only',
      inputs: [
        'aabaacaadaabaaba\naabaa',
        'hello\nll',
        'abcabcabc\nabc',
        'aaaaa\nb',
        'abababab\nabab',
        'xyz\nxy',
        'codecode\ncode',
      ],
      solve(input) {
        const lines = input.split('\n');
        const text = lines[0] ?? '';
        const pattern = lines[1] ?? '';
        const positions = [];
        let idx = text.indexOf(pattern);
        while (idx !== -1) {
          positions.push(idx);
          idx = text.indexOf(pattern, idx + 1);
        }
        return positions.length ? positions.join(' ') : '-1';
      },
    },
  ],
};